(()=>{let e=0,t=0,s=0;document.addEventListener("scroll",()=>e++,{passive:!0}),document.addEventListener("click",()=>t++,{passive:!0}),document.addEventListener("keydown",()=>s++,{passive:!0}),setInterval(()=>{if(!(e===0&&t===0&&s===0)){try{chrome.runtime.sendMessage({type:"ACTIVITY",scrolls:e,clicks:t,keys:s,url:location.hostname})}catch{}e=0,t=0,s=0}},1e4)})();
